CREATE TABLE `products` (
  `Product_ID` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Product_Name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Category` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Subcategory` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Order_ID` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Order_Date` date DEFAULT NULL,
  `Quantity` int DEFAULT NULL,
  `Unit_Price` decimal(18,2) DEFAULT NULL,
  `Gross_Sales` decimal(18,2) DEFAULT NULL,
  `Discount_Pct` int DEFAULT NULL,
  `Net_Sales` decimal(18,2) DEFAULT NULL,
  `Order_Status` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Sales_Channel` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`Order_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
